import json
MEASURE = r"""
(() => {
  const stage = document.querySelector('.doc-stage');
  const bundle = [...document.scripts].map(s=>s.src).filter(Boolean).join(',');
  const btns = [...document.querySelectorAll('button[aria-pressed]')].map(b=>({t:(b.textContent||'').trim(), on:b.getAttribute('aria-pressed')}));
  const rendered = el => !!el && getComputedStyle(el).display !== 'none' && !!el.getClientRects().length;
  const paras = [...document.querySelectorAll('.blk-p')];
  let zhVisible=0, zhHasText=0, enVisible=0, blank=0;
  paras.forEach(p=>{
    const z=p.querySelector('.t-zh'), e=p.querySelector('.t-en');
    const zv=rendered(z), ev=rendered(e);
    if(zv) zhVisible++;
    if(ev) enVisible++;
    const zt=zv? (z.innerText||'').trim() : '';
    const et=ev? (e.innerText||'').trim() : '';
    if(!zt && !et) blank++;
    if(zt) zhHasText++;
  });
  const h = paras.slice(0,6).map(p=>Math.round(p.getBoundingClientRect().height));
  return {url: location.href, bundle, scrollY: Math.round(scrollY), stage: stage? stage.className : null,
          total_p: paras.length, zh_rendered: zhVisible, zh_with_text: zhHasText, en_rendered: enVisible,
          blank_paras: blank, first_heights: h, mode_btns: btns};
})()
"""
targets = cdp("Target.getTargets")["targetInfos"]
out = []
for t in targets:
    if t.get("type") != "page":
        continue
    u = t.get("url", "")
    if "papershelf" in u or "8012" in u:
        try:
            r = js(MEASURE, target_id=t["targetId"])
        except Exception as e:
            r = {"error": str(e)}
        out.append({"targetId": t["targetId"][:8], "url": u, "res": r})
for o in out:
    print(json.dumps(o, ensure_ascii=False, indent=1))
    print("-" * 60)
